/**
 * Cleanup tool: removes every entry whose `provenance.model` matches
 * `--model`, for one locale's corpus file — e.g. to strip out a batch
 * generated by a model that turned out not to be good enough, without
 * touching anything else.
 *
 * Dry run by default (lists what would be removed, writes nothing); pass
 * `--apply` to actually write. `--apply` always backs up the corpus file
 * first, into `tools/corpus-gen/backups/` (the same convention already used
 * for #368's full-corpus regeneration), since this is destructive and
 * `writeCorpus()` itself has no support for removal at all — its own doc
 * comment: "never reordered or removed, only replaced in place or appended
 * after". This uses `lib/write-corpus.mjs`'s `removeCorpusEntries()`
 * instead, a surgical span-based delete that touches nothing else
 * byte-for-byte.
 *
 * Refuses to run against a locale that a `generate-batch.mjs` process is
 * currently regenerating: that process holds its own in-memory copy of the
 * corpus and periodically overwrites the file from it — if this script
 * deletes entries out from under it, the running process's *next* write
 * would find the file's entries no longer line up with its own in-memory
 * array at each index and crash (`writeCorpus`'s own invariant check), or
 * silently resurrect a "removed" entry when it next persists. Wait for that
 * process to finish (or stop it) before running this against the same
 * locale.
 *
 *   npx tsx tools/corpus-gen/remove-by-model.mjs --locale=en --model=<model-name> [--persona=<id>] [--apply]
 */
import { readFile, mkdir, copyFile } from 'node:fs/promises';
import { execSync } from 'node:child_process';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { removeCorpusEntries } from './lib/write-corpus.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');

const rawArgs = process.argv.slice(2);
function flag(name, fallback) {
  const found = rawArgs.find((arg) => arg.startsWith(`--${name}=`));
  return found ? found.slice(name.length + 3) : fallback;
}

const locale = flag('locale');
if (locale !== 'en' && locale !== 'nl') throw new Error('--locale=en|nl is required');
const model = flag('model');
if (!model) throw new Error('--model=<name> is required — e.g. --model=gemini-3.5-flash-lite');
const personaFilter = flag('persona'); // omit to match every persona, including neutral
const apply = rawArgs.includes('--apply');

/** Best-effort guard against the exact hazard this file's own doc comment describes — a `ps`
 * scrape, not a lock file, so it can miss a process started under a very different invocation
 * string, but catches the common case (including this project's own #368 regeneration runs). */
function assertNoConcurrentGeneration(locale) {
  let psOutput;
  try {
    psOutput = execSync('ps aux', { encoding: 'utf8' });
  } catch {
    return; // ps unavailable — fail open rather than block on a platform where this can't check
  }
  const pattern = new RegExp(`generate-batch\\.mjs[^\\n]*--locale=${locale}\\b`);
  if (pattern.test(psOutput)) {
    throw new Error(
      `a generate-batch.mjs process appears to be running for --locale=${locale} right now — ` +
        'removing entries while it runs risks a crash or a silently-resurrected entry on its next ' +
        "write (see this file's own doc comment). Wait for it to finish, or stop it, first.",
    );
  }
}

if (apply) assertNoConcurrentGeneration(locale);

const corpusPath = join(root, 'src', 'interpretation', 'corpus', `${locale}.json`);
const corpus = JSON.parse(await readFile(corpusPath, 'utf8'));

function matches(entry) {
  if (entry.provenance?.model !== model) return false;
  if (personaFilter !== undefined && (entry.persona ?? 'neutral') !== personaFilter) return false;
  return true;
}

const matching = corpus.filter(matches);
console.log(
  `[${locale}] ${String(matching.length)} entr${matching.length === 1 ? 'y' : 'ies'} match model "${model}"` +
    `${personaFilter ? ` (persona=${personaFilter})` : ' (any persona, including neutral)'}.`,
);
for (const entry of matching.slice(0, 20)) console.log(`  ${entry.key}${entry.persona ? ` (${entry.persona})` : ''}`);
if (matching.length > 20) console.log(`  ... and ${String(matching.length - 20)} more`);

if (matching.length === 0) {
  console.log(`[${locale}] nothing to do.`);
  process.exit(0);
}

if (!apply) {
  console.log(
    `\n[${locale}] dry run — nothing written. Re-run with --apply to actually remove ${String(matching.length)} entr${matching.length === 1 ? 'y' : 'ies'}.`,
  );
  process.exit(0);
}

const backupDir = join(root, 'tools', 'corpus-gen', 'backups');
await mkdir(backupDir, { recursive: true });
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
const backupPath = join(backupDir, `${locale}.${timestamp}.json`);
await copyFile(corpusPath, backupPath);
console.log(`[${locale}] backed up current corpus to ${backupPath}`);

const { removedKeys } = await removeCorpusEntries(corpusPath, matches);
console.log(`[${locale}] removed ${String(removedKeys.length)} entr${removedKeys.length === 1 ? 'y' : 'ies'}.`);
